  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  background-color: var(--color-bg);
  color: var(--color-text);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 20px;
}

a {
  color: var(--color-link);
  text-decoration: underline;
}

p a {
  text-decoration: underline;
}

:focus-visible {
  outline: 3px solid var(--color-link);
  outline-offset: 2px;
}

.site-header :focus-visible,
.site-footer :focus-visible {
  outline: 3px solid var(--color-text-on-dark);
  outline-offset: 2px;
}

.site-header {
  background-color: var(--color-surface-dark);
  color: var(--color-text-on-dark);
  padding-bottom: 12px;
}

.utility-bar {
  border-bottom: 1px solid var(--color-border);
  padding: 8px 0;
}

.header-main {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 12px;
}

.brand-logo {
  display: inline-block;
  min-height: 44px;
  line-height: 44px;
  padding: 0 8px;
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text-on-dark);
  text-decoration: none;
}

.nav-list,
.panel-nav-list,
.footer-links,
.social,
.product-grid,
.cart-list,
.summary-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.nav-list a,
.panel-nav-list a,
.footer-links a {
  display: inline-block;
  min-height: 44px;
  line-height: 44px;
  padding: 0 10px;
  color: var(--color-text-on-dark);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.icon-control {
  display: inline-block;
  width: 44px;
  height: 44px;
  padding: 10px;
  background-color: var(--color-surface-dark);
  color: var(--color-text-on-dark);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  text-align: center;
  cursor: pointer;
}

.header-panel {
  border-top: 1px solid var(--color-border);
  margin-top: 12px;
  padding-top: 16px;
}

.search-form label {
  display: block;
  margin-bottom: 6px;
  color: var(--color-text-on-dark);
}

.search-controls,
.newsletter-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

input,
select {
  min-height: 44px;
  padding: 8px 12px;
  font-size: 16px;
  font-family: inherit;
  color: var(--color-text);
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 4px;
}

button,
.btn-link {
  display: inline-block;
  min-height: 44px;
  padding: 10px 20px;
  font-size: 16px;
  font-family: inherit;
  font-weight: 600;
  line-height: 1.4;
  border-radius: 4px;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary,
.btn-link {
  background-color: var(--color-accent);
  color: var(--color-text-on-dark);
  border: 1px solid var(--color-accent);
}

.btn-secondary {
  background-color: var(--color-bg);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}

.hero-banner {
  padding: 28px 0 16px;
}

.collection-section,
.related,
.newsletter-section {
  padding: 28px 0;
  border-top: 1px solid var(--color-border);
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 28px;
}

.product-card {
  border: 1px solid var(--color-border);
  padding: 16px;
  background-color: var(--color-bg);
}

.card-link {
  display: inline-block;
  min-height: 44px;
  padding: 8px 0;
  color: var(--color-link);
}

.price {
  font-weight: 600;
  margin: 6px 0 0;
}

.product-detail,
.checkout-layout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  padding: 28px 0;
}

.form-row {
  margin-bottom: 16px;
}

.form-row label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
}

.form-row input,
.form-row select {
  width: 100%;
  max-width: 380px;
}

.cart-list {
  display: grid;
  gap: 20px;
  margin: 24px 0;
}

.cart-line {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border: 1px solid var(--color-border);
}

.cart-summary,
.order-summary {
  padding: 20px;
  border: 1px solid var(--color-border);
  margin-bottom: 28px;
}

.site-footer {
  background-color: var(--color-surface-dark);
  color: var(--color-text-on-dark);
  padding: 36px 0;
}

.footer-col p {
  color: var(--color-text-on-dark-soft);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-bottom: 24px;
}

.social {
  display: flex;
  gap: 12px;
}

.product-meta, .shipping-note, .line-meta, .cart-note,
.field-hint, .summary-note, .utility-note, .footer-note {
  color: var(--color-text-muted);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
  margin: 6px 0;
}

3.js/main.js:
(function () {
  function setupToggle(buttonSelector, panelId) {
    var button = document.querySelector(buttonSelector);
    var panel = document.getElementById(panelId);
    if (!button || !panel) {
      return;
    }
    button.addEventListener('click', function () {
      var isHidden = panel.hasAttribute('hidden');
      if (isHidden) {
        panel.removeAttribute('hidden');
        button.setAttribute('aria-expanded', 'true');
      } else {
        panel.setAttribute('hidden', '');
        button.setAttribute('aria-expanded', 'false');
      }
    });
  }

  setupToggle('.search-toggle', 'search-panel');
  setupToggle('.menu-toggle', 'menu-panel');

  var forms = document.querySelectorAll('form');
  for (var i = 0; i < forms.length; i++) {
    forms[i].addEventListener('submit', function (event) {
      event.preventDefault();
      var status = this.querySelector('.form-status');
      if (status) {
        status.textContent = 'Demo store: nothing was sent.';
        status.removeAttribute('hidden');
      }
    });
  }
})();

